import json

pairs = [("What is a token?", "A chunk of text the model reads."),
         ("", "orphan answer"),
         ("What is RAG?", "Retrieve relevant text, then generate an answer from it.")]

def to_jsonl(pairs, system):
    lines = []
    for q, a in pairs:
        if not q.strip() or not a.strip():
            continue
        ex = {"messages": [{"role": "system", "content": system},
                           {"role": "user", "content": q},
                           {"role": "assistant", "content": a}]}
        lines.append(json.dumps(ex))
    return "\n".join(lines)

