class Cache:
    def __init__(self, ttl):
        self.ttl = ttl
        self.store = {}
        self.hits = 0
        self.misses = 0

    def key(self, model, prompt):
        return model + "::" + prompt.strip().lower()

    def get(self, model, prompt, now):
        k = self.key(model, prompt)
        if k in self.store:
            answer, saved_at = self.store[k]
            if now - saved_at < self.ttl:
                self.hits += 1
                return answer
        self.misses += 1
        return None

    def set(self, model, prompt, answer, now):
        self.store[self.key(model, prompt)] = (answer, now)

    def hit_rate(self):
        total = self.hits + self.misses
        return self.hits / total if total else 0.0

c = Cache(ttl=60)
print(c.get("mini", "What is RAG?", now=0))
c.set("mini", "What is RAG?", "Retrieval-augmented generation", now=0)
print(c.get("mini", "  what is rag?  ", now=10), c.hit_rate())

