def openai_down(prompt):  raise TimeoutError("timed out")
def claude_limited(prompt): raise RuntimeError("429 rate limit")
def local_ollama(prompt): return f"(local model) {prompt[::-1]}"

def call_with_fallback(providers, prompt):
    errors = []
    for name, fn in providers:
        try:
            return {"provider": name, "reply": fn(prompt), "errors": errors}
        except Exception as e:
            errors.append(f"{name}: {e}")
    return {"provider": None, "reply": None, "errors": errors}

print(call_with_fallback([("openai", openai_down), ("anthropic", claude_limited), ("ollama", local_ollama)], "hello"))
